# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">KUR\'AN\'DAN MESAJLAR: NİSÂ SURESİ 69. AYET VE DÖRT ÖNCÜ ZÜMRE</text>\n  <rect x="20" y="42" width="660" height="44" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="61" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">"Kim Allah\'a ve Peygamber\'e itaat ederse, işte onlar Allah\'ın kendilerine nimet verdiği</text>\n  <text x="350" y="77" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">peygamberler, sıddıklar, şehitler ve salihlerle beraberdir. Bunlar ne güzel arkadaştır!" (Nisâ, 4/69)</text>\n  <rect x="20" y="98" width="155" height="145" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="97" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Nebîler</text>\n  <text x="97" y="136" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">(Peygamberler)</text>\n  <text x="97" y="158" text-anchor="middle" font-size="10" fill="#1e3a8a">Allah\'tan aldıkları vahyi</text>\n  <text x="97" y="174" text-anchor="middle" font-size="10" fill="#1e3a8a">insanlığa tebliğ eden ve</text>\n  <text x="97" y="190" text-anchor="middle" font-size="10" fill="#1e3a8a">yaşayarak örnek olan</text>\n  <text x="97" y="206" text-anchor="middle" font-size="10" fill="#1e3a8a">seçilmiş elçilerdir.</text>\n  <rect x="188" y="98" width="155" height="145" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="265" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Sıddıklar</text>\n  <text x="265" y="136" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">(Dosdoğru Olanlar)</text>\n  <text x="265" y="158" text-anchor="middle" font-size="10" fill="#14532d">Allah\'a ve Peygamber\'e</text>\n  <text x="265" y="174" text-anchor="middle" font-size="10" fill="#14532d">tereddütsüz iman eden,</text>\n  <text x="265" y="190" text-anchor="middle" font-size="10" fill="#14532d">özü sözü bir, sadakat</text>\n  <text x="265" y="206" text-anchor="middle" font-size="10" fill="#14532d">ve doğruluk timsalleridir.</text>\n  <rect x="356" y="98" width="155" height="145" rx="8" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="433" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">3. Şehitler</text>\n  <text x="433" y="136" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">(Şahitler / Fedakârlar)</text>\n  <text x="433" y="158" text-anchor="middle" font-size="10" fill="#7f1d1d">Allah yolunda, din, vatan,</text>\n  <text x="433" y="174" text-anchor="middle" font-size="10" fill="#7f1d1d">bayrak ve mukaddesat</text>\n  <text x="433" y="190" text-anchor="middle" font-size="10" fill="#7f1d1d">uğrunda canlarını feda</text>\n  <text x="433" y="206" text-anchor="middle" font-size="10" fill="#7f1d1d">eden müminlerdir.</text>\n  <rect x="525" y="98" width="155" height="145" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="602" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">4. Salihler</text>\n  <text x="602" y="136" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">(İyi ve Hayırlı Kullar)</text>\n  <text x="602" y="158" text-anchor="middle" font-size="10" fill="#581c87">İmanlarını salih amellerle</text>\n  <text x="602" y="174" text-anchor="middle" font-size="10" fill="#581c87">bütünleştiren, ahlaklı,</text>\n  <text x="602" y="190" text-anchor="middle" font-size="10" fill="#581c87">kul hakkını gözeten ve</text>\n  <text x="602" y="206" text-anchor="middle" font-size="10" fill="#581c87">topluma faydalı kullardır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">NİSÂ 69. AYETİN NÜZUL SEBEBİ (SEBEB-İ NÜZULÜ) VE İTAAT BİLİNCİ</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Hz. Sevban\'ın (r.a.) Peygamber Sevgisi</text>\n  <text x="40" y="94" font-size="10.5" fill="#1e3a8a">• Sahabeden <tspan font-weight="bold">Hz. Sevban (r.a.)</tspan>, Hz. Peygamber\'i</text>\n  <text x="48" y="110" font-size="10.5" fill="#1e3a8a">görmediği zaman derin bir hüzne kapılırdı.</text>\n  <text x="40" y="132" font-size="10.5" fill="#1e3a8a">• Bir gün üzüntüyle huzura gelerek: "Ey Allah\'ın</text>\n  <text x="48" y="148" font-size="10.5" fill="#1e3a8a">Resulü! Cennette sen peygamberlerin yüce</text>\n  <text x="48" y="164" font-size="10.5" fill="#1e3a8a">makamında olacaksın, ben ise daha alt</text>\n  <text x="48" y="180" font-size="10.5" fill="#1e3a8a">derecede kalıp seni görememekten korkuyorum"</text>\n  <text x="48" y="196" font-size="10.5" fill="#1e3a8a">diyerek endişesini dile getirmiştir.</text>\n  <text x="40" y="218" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Bunun üzerine müjde olarak Nisâ 69. ayet inmiştir.</text>\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Fâtiha Suresi İle Anlam Bütünlüğü</text>\n  <text x="380" y="94" font-size="10.5" fill="#14532d">• Her namazda okuduğumuz <tspan font-weight="bold">Fâtiha Suresi 6-7.</tspan></text>\n  <text x="388" y="110" font-size="10.5" fill="#14532d"><tspan font-weight="bold">ayetlerde</tspan> "Bizi صراط المستقيم\'e (kendilerine</text>\n  <text x="388" y="126" font-size="10.5" fill="#14532d">nimet verdiklerinin yoluna) ilet" diye dua ederiz.</text>\n  <text x="380" y="150" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Nisâ Suresi 69. ayet</tspan>, Fâtiha\'daki "kendilerine</text>\n  <text x="388" y="166" font-size="10.5" fill="#14532d">nimet verilenlerin" kimler olduğunu açıklar:</text>\n  <text x="388" y="184" font-size="11" font-weight="bold" fill="#15803d">Nebîler + Sıddıklar + Şehitler + Salihler</text>\n  <text x="380" y="208" font-size="10.5" fill="#14532d">• Hadis-i Şerif: <tspan font-weight="bold">"Kişi sevdiği ile beraberdir."</tspan></text>\n  <text x="388" y="224" font-size="10" fill="#166534">(Buhârî, Edeb, 96; Müslim, Birr, 165)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">2. ÜNİTE GENEL DEĞERLENDİRMESİ: ANADOLU\'DA İSLAM VE MANEVİ MİMARLAR</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">1. İslamlaşma ve Kurumlar</text>\n  <text x="32" y="90" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Horasan — Mâverâünnehir:</tspan></text>\n  <text x="40" y="106" font-size="10" fill="#78350f">Semerkant, Buhara, Taşkent</text>\n  <text x="32" y="128" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Ribâtlar ve Kervansaraylar:</tspan></text>\n  <text x="40" y="144" font-size="10" fill="#78350f">Sınır güvenliği ve tebliğ merkezleri</text>\n  <text x="32" y="166" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Medrese ve Darülhadisler:</tspan></text>\n  <text x="40" y="182" font-size="10" fill="#78350f">Nizamiye, Karatay, Sahn-ı Seman</text>\n  <text x="32" y="204" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Fütüvvet ve Ahilik:</tspan></text>\n  <text x="40" y="220" font-size="10" fill="#78350f">Meslek ahlakı ve esnaf dayanışması</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">2. Fıkıh ve İtikat Önderleri</text>\n  <text x="257" y="90" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Ebû Hanîfe:</tspan> Fıkh-ı Ekber</text>\n  <text x="257" y="112" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Ca\'fer es-Sâdık:</tspan> Ehl-i Beyt âlimi</text>\n  <text x="257" y="134" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">İmam Şâfiî:</tspan> er-Risâle, el-Ümm</text>\n  <text x="257" y="156" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">İmam Mâtürîdî:</tspan> Kitâbü\'t-Tevhîd,</text>\n  <text x="265" y="172" font-size="10" fill="#1e3a8a">Te\'vîlâtü\'l-Kur\'ân (Akıl-vahiy dengesi)</text>\n  <text x="257" y="196" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">İmam Eş\'arî:</tspan> el-İbâne, Makâlâtü\'l-</text>\n  <text x="265" y="212" font-size="10" fill="#1e3a8a">İslâmiyyîn (Sünni kelam ekolü)</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">3. Gönül Erenleri (Sıddık/Salih)</text>\n  <text x="482" y="90" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Ahmet Yesevî:</tspan> Dîvân-ı Hikmet</text>\n  <text x="482" y="112" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Mevlânâ:</tspan> Mesnevî, Dîvân-ı Kebîr</text>\n  <text x="482" y="134" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Hacı Bektâş-ı Velî:</tspan> Makâlât</text>\n  <text x="482" y="156" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Ahi Evran:</tspan> Letâif-i Hikmet</text>\n  <text x="482" y="178" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Yunus Emre:</tspan> Risâletü\'n-Nushiyye</text>\n  <text x="482" y="200" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Sarı Saltuk:</tspan> Balkanlar\'ın irşadı</text>\n  <text x="482" y="220" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Hacı Bayram-ı Velî:</tspan> Ankara/Bayramiyye</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
